#include <queue>
#include <iostream>

void safe_pop(std::queue<int>& q) {
    if (q.empty()) {
        // Handle error gracefully
        std::cerr << "Error: Queue is empty.\n";
        return;
    }

    // Correct split operation
    int value = q.front(); // 1. Access
    q.pop();             // 2. Remove (void)
    std::cout << "Popped: " << value << "\n";
}

int main() {
    std::queue<int> q;
    safe_pop(q); // Safe check
    // q.pop(); // DANGER: UB if called here without check
}
